    url.searchParams.sort();
    const path = url.pathname.replace(/\/+$/, '') || '/';
    return `${url.hostname}${url.port ? `:${url.port}` : ''}${path}${url.search}`;
  } catch { return value.trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/[\/#]+$/, ''); }
}

